package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome1620 {
    data class Success(val payload: String) : Outcome1620()
    data object Failure : Outcome1620()
}

fun describe1620(outcome: Outcome1620): String = when (outcome) {
    is Outcome1620.Success -> outcome.payload
    Outcome1620.Failure -> "failed"
}
class Counter1621 {
    var current: Int by Delegates.observable(81) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
